const body = $input.item.json.body || $input.item.json;
const action = body.action || '';
const key = $input.item.json.headers?.['x-impar-key'] || body.key || '';
const { execSync } = require('child_process');
let envKey = '';
try { envKey = execSync('grep IMPAR_WEBHOOK_KEY ~/.impar-n8n-core/.env | cut -d= -f2-', {timeout:3000}).toString().trim(); } catch(e) {}
if (key !== envKey || !key) return [{ json: { error: 'unauthorized', ai_used: false, timestamp: new Date().toISOString() } }];
if (!action || typeof action !== 'string' || action.length > 50) return [{ json: { error: 'invalid_action', ai_used: false } }];
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
let whitelist = {};
try { whitelist = JSON.parse(require('fs').readFileSync(`${prj}/IMPAR_OS/config/whitelist.json`,'utf8')).actions; } catch(e) {}
const entry = whitelist[action];
if (!entry) return [{ json: { error: 'action_not_in_whitelist', action, ai_used: false } }];
if (entry.category === 'BLOCKED') return [{ json: { error: 'action_blocked', action, ai_used: false } }];
if (entry.category === 'REQUIRES_APPROVAL') return [{ json: { error: 'requires_approval', action, ai_used: false } }];
if (entry.category !== 'READ_ONLY_AUTO') return [{ json: { error: 'not_auto', action, ai_used: false } }];
let out = '';
if (entry.command && entry.command !== 'MARKETPLACE_STATUS_ONLY') {
  try { out = execSync(`${prj}/IMPAR_OS/bin/impar-os ${entry.command.replace('impar-os ','')} 2>&1`, {timeout:15000}).toString(); } catch(e) { out = e.message; }
}
return [{ json: { status: 'ok', action, category: entry.category, ai_used: false, timestamp: new Date().toISOString(), output: out.substring(0,1000) } }];
